"""Regression coverage for wrapped Maybe decider declarations."""

from unittest import mock

import pytest

import factory


@pytest.mark.parametrize('chance, expected', [(0, 'no'), (100, 'yes')])
@pytest.mark.parametrize('locale', [None, 'en_US', 'fr_FR'])
def test_faker_decider_defaults(chance, expected, locale):
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('boolean', chance_of_getting_true=chance, locale=locale),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == expected


def test_faker_decider_resolves_declaration_arguments():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker(
                'boolean', chance_of_getting_true=factory.LazyFunction(lambda: 100),
            ),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == 'yes'


def test_overrides_belong_to_selected_declaration():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Faker('boolean', locale='fr_FR', chance_of_getting_true=100),
            yes_declaration=factory.Faker('pyint', min_value=1, max_value=1),
        )

    with mock.patch.object(factory.Faker, '_get_faker', wraps=factory.Faker._get_faker) as get_faker:
        assert ExampleFactory(result__locale='en_US', result__min_value=2, result__max_value=2)['result'] == 2
    assert get_faker.call_args_list == [mock.call('fr_FR'), mock.call('en_US')]


def test_nested_maybe_decider():
    class ExampleFactory(factory.DictFactory):
        result = factory.Maybe(
            factory.Maybe(factory.LazyFunction(lambda: True), True, False),
            yes_declaration='yes',
            no_declaration='no',
        )

    assert ExampleFactory()['result'] == 'yes'
